  `SQN_ID` VARCHAR(35) NOT NULL,
  `SQN_DESC` VARCHAR(255) NULL,
  `SQN_KEY` VARCHAR(35) NULL,
  `SQN_SEQ` INT NULL,
  `SQN_DT_CREATE` DATETIME NULL,
  `SQN_UID_CREATE` VARCHAR(35) NULL,
  `SQN_DT_LUPD` DATETIME NULL,
  `SQN_UID_LUPD` VARCHAR(35) NULL,
  PRIMARY KEY (`SQN_ID`));


