ALTER TABLE `T_CK_JOB_TRUCK` 
ADD COLUMN `JOB_TOTAL_PLATFORM_FEES` DECIMAL(15,2) NULL AFTER `JOB_TOTAL_REIMBURSEMENTS`;

ALTER TABLE `T_CK_CT_DEBIT_NOTE` 
ADD COLUMN `DN_DT_DUE` DATETIME NULL DEFAULT NULL COMMENT 'DEBIT NOTE DATE' AFTER `DN_DT_ISSUE`,
ADD COLUMN `DN_NAME` VARCHAR(256) NULL DEFAULT NULL COMMENT 'DEBIT NOTE FILE NAME' AFTER `DN_TO`,
ADD COLUMN `DN_LOC` VARCHAR(1024) NULL DEFAULT NULL COMMENT 'DEBIT NOTE PATH' AFTER `DN_NAME`;

ALTER TABLE `T_CK_CT_DEBIT_NOTE` 
ADD COLUMN `DN_AMOUNT` DECIMAL(15,2) NULL AFTER `DN_AGE_BAND`;

CREATE TABLE `T_CK_CT_PLATFORM_INVOICE` (
  `INV_ID` varchar(35) NOT NULL COMMENT 'INVOICE ID - UUID',
  `INV_STATE` varchar(35) NOT NULL COMMENT 'INVOICE STATE - REFERENCES T_CK_CT_MST_TO_INVOICE_STATE:INST_ID',
  `INV_JOB_ID` varchar(35) DEFAULT NULL COMMENT 'JOB ID - NO REFERENCE HERE JUST FOR QUICK JOINT',
  `INV_TRIP` varchar(35) DEFAULT NULL COMMENT 'TRIP INVOICE - REFERENCE T_CK_CT_TRIP:TR_ID',
  `INV_NO` varchar(256) NOT NULL COMMENT 'INVOICE NUMBER - PROVIDED BY TO',
  `INV_DT_ISSUE` datetime DEFAULT NULL COMMENT 'INVOICE ISSUE DATE',
  `INV_DT_DUE` datetime DEFAULT NULL COMMENT 'INVOICE DUE DATE',
  `INV_FROM` varchar(35) DEFAULT NULL COMMENT 'INVOICE FROM - REFERENCES T_CORE_ACCN:ACCN_ID',
  `INV_TO` varchar(35) DEFAULT NULL COMMENT 'INVOICE TO - REFERENCES T_CORE_ACCN:ACCN_ID',
  `INV_NAME` varchar(256) DEFAULT NULL COMMENT 'INVOICE FILE NAME',
  `INV_LOC` varchar(1024) DEFAULT NULL COMMENT 'INVOICE PATH AS ZIP FILE IF THERE ARE MUTLIPLE INVOICES REFERENCE FROM SYS_PARAM SETUP',
  `INV_INVOCIER_COMMENT` mediumtext COMMENT 'COMMENTS BY INVOICER',
  `INV_INVOCIEE_REMARKS` mediumtext COMMENT 'REMARKS BY INVOICEE',
  `INV_STATUS` char(1) DEFAULT NULL COMMENT 'REIMBURSEMENT STATUS',
  `INV_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `INV_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `INV_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `INV_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`INV_ID`),
  CONSTRAINT `FK_CK_CT_PLATFORM_INVOICE_CK_CT_MST_TO_INVOICE_STATE` FOREIGN KEY (`INV_STATE`) REFERENCES `T_CK_CT_MST_TO_INVOICE_STATE` (`INST_ID`),
  CONSTRAINT `FK_CK_CT_PLATFORM_INVOICE_CK_CT_TRIP` FOREIGN KEY (`INV_TRIP`) REFERENCES `T_CK_CT_TRIP` (`TR_ID`),
  CONSTRAINT `FK_CK_CT_PLATFORM_INVOICE_CORE_ACCN1` FOREIGN KEY (`INV_FROM`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_CT_PLATFORM_INVOICE_CORE_ACCN2` FOREIGN KEY (`INV_TO`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='PLATFORM FEE INVOICE TABLE';


ALTER TABLE `T_CK_CT_PLATFORM_INVOICE` 
ADD COLUMN `INV_AMOUNT` DECIMAL(15,2) NULL AFTER `INV_NO`;

ALTER TABLE `T_CK_PAYMENT_AUDIT` 
CHANGE COLUMN `PYA_STATE` `PYA_STATE` VARCHAR(35) NULL DEFAULT NULL ;


ALTER TABLE `T_CK_CT_LOCATION` 
ADD COLUMN `LOC_LATITUDE` VARCHAR(1024) NULL AFTER `LOC_REMARKS`,
ADD COLUMN `LOC_LONGITUDE` VARCHAR(1024) NULL AFTER `LOC_LATITUDE`;

