-- 2023-June-11 changes to platform invoice and debit note tables --- 
ALTER TABLE `T_CK_CT_PLATFORM_INVOICE` 
DROP COLUMN `INV_AMOUNT`;

ALTER TABLE `T_CK_CT_PLATFORM_INVOICE` 
ADD COLUMN `INV_AMT` DECIMAL(15,2) NULL DEFAULT 0.0 AFTER `INV_TO`,
ADD COLUMN `INV_VAT` DECIMAL(15,2) NULL DEFAULT 0.0 AFTER `INV_AMT`,
ADD COLUMN `INV_STAMP_DUTY` DECIMAL(15,2) NULL DEFAULT 0.0 AFTER `INV_VAT`,
ADD COLUMN `INV_TOTAL` DECIMAL(15,2) NULL DEFAULT 0.0 AFTER `INV_STAMP_DUTY`;

ALTER TABLE `T_CK_CT_DEBIT_NOTE` 
DROP COLUMN `DN_AMOUNT`;


ALTER TABLE `T_CK_CT_DEBIT_NOTE` 
ADD COLUMN `DN_AMT` DECIMAL(15,2) NULL DEFAULT 0.0 AFTER `DN_TO`,
ADD COLUMN `DN_VAT` DECIMAL(15,2) NULL DEFAULT 0.0 AFTER `DN_AMT`,
ADD COLUMN `DN_STAMP_DUTY` DECIMAL(15,2) NULL DEFAULT 0.0 AFTER `DN_VAT`,
ADD COLUMN `DN_TOTAL` DECIMAL(15,2) NULL DEFAULT 0.0 AFTER `DN_STAMP_DUTY`;


CREATE TABLE `T_CK_CT_PLATFORM_INVOICE_ITEM` (
  `ITM_ID` varchar(35) NOT NULL COMMENT 'INVOICE ITEM ID - UUID',
  `ITM_INVOICE` varchar(35) DEFAULT NULL COMMENT 'PLATFORM INVOICE REFERENCES - T_CK_CT_PLATFORM_INVOICE:INV_ID',
  `ITM_SNO` smallint COMMENT 'SEQUENCE NUMBER OF THE ITEM - 1,2,3',  
  `ITM_ITEM` mediumtext COMMENT 'DESCRIPTION OF THE ITEM IN INVOICE',
  `ITM_QTY` smallint DEFAULT '0' COMMENT 'QTY OF THE ITEM IN INVOICE',
  `ITM_CCY` varchar(3) DEFAULT NULL COMMENT 'CURRENCY OF THE PAYMENT - REFERENCES T_MST_CURRENCY:CCY_CODE',
  `ITM_UNIT_PRICE` decimal(15,2) DEFAULT '0.00' COMMENT 'UNIT PRICE OF THE ITEM',
  `ITM_AMOUNT` decimal(15,2) DEFAULT '0.00' COMMENT 'AMOUNT TO BE ITEM TO BE PAID',
  `ITM_REF` mediumtext COMMENT 'REFERENCES FOR ITEM TO BE PAID - JOB NUMBER : TRIP NUMBER',
  `ITM_STATUS` char(1) DEFAULT NULL COMMENT 'PAYMENT RECORD AUDIT TYPE STATUS',
  `ITM_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `ITM_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `ITM_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `ITM_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`ITM_ID`),
  CONSTRAINT `FK_CK_CT_PLATFORM_INVOICE_ITEM_CK_CT_PLATFORM_INVOICE` FOREIGN KEY (`ITM_INVOICE`) REFERENCES `T_CK_CT_PLATFORM_INVOICE` (`INV_ID`),
  CONSTRAINT `FK_CK_CT_PLATFORM_INVOICE_ITEM_MST_CURRENCY` FOREIGN KEY (`ITM_CCY`) REFERENCES `T_MST_CURRENCY` (`CCY_CODE`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='PLATFORM INVOICE ITEM';



CREATE TABLE `T_CK_CT_DEBIT_NOTE_ITEM` (
  `ITM_ID` varchar(35) NOT NULL COMMENT 'INVOICE ITEM ID - UUID',
  `ITM_DEBIT_NOTE` varchar(35) DEFAULT NULL COMMENT 'DEBIT NOTE REFERENCES - T_CK_CT_DEBIT_NOTE:DN_ID',
  `ITM_SNO` smallint COMMENT 'SEQUENCE NUMBER OF THE ITEM - 1,2,3',  
  `ITM_ITEM` mediumtext COMMENT 'DESCRIPTION OF THE ITEM IN INVOICE',
  `ITM_QTY` smallint DEFAULT '0' COMMENT 'QTY OF THE ITEM IN INVOICE',
  `ITM_CCY` varchar(3) DEFAULT NULL COMMENT 'CURRENCY OF THE PAYMENT - REFERENCES T_MST_CURRENCY:CCY_CODE',
  `ITM_UNIT_PRICE` decimal(15,2) DEFAULT '0.00' COMMENT 'UNIT PRICE OF THE ITEM',
  `ITM_AMOUNT` decimal(15,2) DEFAULT '0.00' COMMENT 'AMOUNT TO BE ITEM TO BE PAID',
  `ITM_REF` mediumtext COMMENT 'REFERENCES FOR ITEM TO BE PAID - JOB NUMBER : TRIP NUMBER',
  `ITM_STATUS` char(1) DEFAULT NULL COMMENT 'PAYMENT RECORD AUDIT TYPE STATUS',
  `ITM_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `ITM_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `ITM_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `ITM_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`ITM_ID`),
  CONSTRAINT `FK_CK_CT_DEBIT_NOTE_ITEM_CK_CT_DEBIT_NOTE` FOREIGN KEY (`ITM_DEBIT_NOTE`) REFERENCES `T_CK_CT_DEBIT_NOTE` (`DN_ID`),
  CONSTRAINT `FK_CK_CT_DEBIT_NOTE_ITEM_MST_CURRENCY` FOREIGN KEY (`ITM_CCY`) REFERENCES `T_MST_CURRENCY` (`CCY_CODE`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='DEBIT NOTE ITEM';



