  `SAGE_BATCH_NO` varchar(35) NOT NULL COMMENT 'SAGE EXCEL FILE BATCH NO.',
  `SAGE_FILE_LOC` varchar(1024) NOT NULL COMMENT 'EXCEL FILE PATH',
  `SAGE_DT_START` datetime NOT NULL COMMENT 'DATA',
  `SAGE_DT_END` datetime NOT NULL COMMENT 'SAGE EXCEL FILE BATCH NO.',
  `SAGE_STATUS` char(1) DEFAULT NULL,
  `SAGE_DT_CREATE` datetime DEFAULT NULL,
  `SAGE_UID_CREATE` varchar(35) DEFAULT NULL,
  `SAGE_DT_LUPD` datetime DEFAULT NULL,
  `SAGE_UID_LUPD` varchar(35) DEFAULT NULL,
  PRIMARY KEY (`SAGE_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;


CREATE TABLE T_CK_CT_SAGE_TAX (
  `ST_ID` varchar(35) NOT NULL,
  `ST_PREFIX` varchar(35) NOT NULL COMMENT 'LIKE: 010.007.23. 010.009.23.',
  `ST_RANGE_BEGIN` BIGINT NOT NULL COMMENT 'LIKE: 899000000',
  `ST_RANGE_END` BIGINT NOT NULL COMMENT 'LIKE: 89009999',
  `ST_RANGE_CURRENT` BIGINT NOT NULL COMMENT 'LIKE: 89001234',
  `ST_RANGE_FORMAT` varchar(35) NOT NULL COMMENT '%8d',
  `ST_STATUS` char(1) DEFAULT 'A'  COMMENT 'E: expired, I: inactive, A:Active',
  `ST_DT_CREATE` datetime DEFAULT NULL,
  `ST_UID_CREATE` varchar(35) DEFAULT NULL,
  `ST_DT_LUPD` datetime DEFAULT NULL,
  `ST_UID_LUPD` varchar(35) DEFAULT NULL,
  PRIMARY KEY (`ST_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;


