CREATE TABLE `T_CK_CT_TO_PAYMENT` (
  `TOP_ID` varchar(35) NOT NULL COMMENT 'UUID',
  `TOP_ACCN_TO` varchar(35) DEFAULT NULL COMMENT 'REFERENCES TO T_CORE_ACCN:ACCNID TRUCKING OPERATOR',
  `TOP_DT_TRANSFER` datetime DEFAULT NULL COMMENT '7 CALENDARS AFTER CO APPROVED INVOICE',
  `TOP_AMT` decimal(15,2) DEFAULT NULL,
  `TOP_REFERENCE` varchar(2048) DEFAULT NULL COMMENT 'T_CK_PAYMENT REFERENCE',
  `TOP_JSON` mediumtext COMMENT 'JSON OBJECT FOR THE API CALL TO CLICPAY PAYMENT GATEWAY FOR FUNDSTRANSFER',
  `TOP_EXCEPTION` mediumtext COMMENT 'EXCEPTION RETURNED BY THE CLICPAY PAYMENT GATEWAY',
  `TOP_STATUS` char(1) DEFAULT NULL COMMENT 'A:ACTIVE; I:INACTIVE',
  `TOP_DT_CREATE` datetime DEFAULT NULL,
  `TOP_UID_CREATE` varchar(35) DEFAULT NULL,
  `TOP_DT_LUPD` datetime DEFAULT NULL,
  `TOP_UID_LUPD` varchar(35) DEFAULT NULL,
  PRIMARY KEY (`TOP_ID`),
  KEY `FK_TOP_ACCN_TO_CORE_ACCN_idx` (`TOP_ACCN_TO`),
  CONSTRAINT `FK_TOP_ACCN_TO_CORE_ACCN` FOREIGN KEY (`TOP_ACCN_TO`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;


