-- 2023-jul-13 new tables for tax modules -- 
CREATE TABLE `T_CK_TAX_INVOICE` (
  `TI_ID` varchar(35) NOT NULL COMMENT 'UNIQUE ID',
  `TI_SERVICE` varchar(35) NOT NULL COMMENT 'CLICKARGO SERVICE - REFERENCES T_CK_MST_SERVICE_TYPE:SVCT_ID',
  `TI_NO` varchar(35) NOT NULL COMMENT 'TAX NO - 010.007.23. 010.009.23.',
  `TI_AMT` decimal(15,2) DEFAULT 0.0 COMMENT 'TAX AMOUNT',
  `TI_DOC` varchar(1024) NOT NULL COMMENT 'FULL PATH PDF LOCATION GENERATED FROM AUTHORIZED SYSTEM',
  `TI_DT_UPLOAD` datetime DEFAULT NULL COMMENT 'DATE TIME WHEN TAX PDF IS UPLOADED',
  `TI_USR_UPLOAD` varchar(35) DEFAULT NULL COMMENT 'USR WHO UPLOADED TAX PDF',
  `TI_INV_NO` varchar(256) NOT NULL COMMENT 'INVOICE NUMBER',
  `TI_INV_DT_ISSUE` datetime DEFAULT NULL COMMENT 'INVOICE ISSUE DATE',
  `TI_JOB_NO` varchar(35) DEFAULT NULL COMMENT 'JOB NUMBER ASSOICATED WITH TAX AND INVOICE',
  `TI_ACCN` varchar(35) DEFAULT NULL COMMENT 'CUSTOMER ACCOUNT - REFERNCES T_CORE_ACCN:ACCN_ID',
  `TI_STATUS` char(1) DEFAULT 'N' COMMENT 'N: NEW E:EXPORTED C: COMPLETED WITH PDF UPLOADED ',
  `TI_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `TI_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `TI_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `TI_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`TI_ID`),
  CONSTRAINT `FK_CK_TAX_INVOICE_CK_MST_SERVICE_TYPE` FOREIGN KEY (`TI_SERVICE`) REFERENCES `T_CK_MST_SERVICE_TYPE` (`SVCT_ID`),  
  CONSTRAINT `FK_CK_TAX_INVOICE_CORE_ACCN` FOREIGN KEY (`TI_ACCN`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT 'TAX INVOICE TABLE';


CREATE TABLE `T_CK_TAX_REPORT` (
  `TR_ID` varchar(35) NOT NULL COMMENT 'UNIQUE ID',
  `TR_NAME` varchar(256) DEFAULT NULL COMMENT 'EXCEL FILE NAME - TAX_CK_DDMMYYYY',
  `TR_DOC` varchar(1024) DEFAULT NULL COMMENT 'FULL PATH EXCEL LOCATION',
  `TR_NUM_RECORDS` mediumint DEFAULT 0 COMMENT 'NUMBER OF RECORDS EXPORTED',
  `TR_STATUS` char(1) DEFAULT 'N' COMMENT 'N: NEW D:DOWNLOADED',
  `TR_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `TR_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `TR_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `TR_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`TR_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT 'TAX REPORT TABLE';

